import { SectionHead } from "march/landing"

// başlık zarı: "Zar at" her basışta başka bir başlık, ölçek ve hiza getirir
const ROLLS = [
  { eyebrow: "🎲 1", title: "Pazartesi sendromuna son", size: "sm", align: "start" },
  { eyebrow: "🎲 2", title: "Kahve bitti, panik yok", size: "md", align: "center" },
  { eyebrow: "🎲 3", title: "Kediler ofisi devraldı", size: "lg", align: "end" },
  { eyebrow: "🎲 4", title: "Bugün her şey mümkün", size: "xl", align: "center" },
] as const

export function HeadlineDice() {
  let $roll = 0
  return <div>
    {() => {
      const r = ROLLS[$roll]!
      return <SectionHead eyebrow={r.eyebrow} title={r.title} size={r.size} align={r.align}
        actions={[{ label: "Zar at", onClick: () => $roll = ($roll + 1) % ROLLS.length }]} note={`${r.size} ölçek · ${r.align} hiza`} />
    }}
  </div>
}

import { SectionHead } from "march/landing"
import { arrowRight, mapPin } from "march/icons"

// bir mahalle fırınının sitesinde sipariş bölümünün açılışı: üst etiket bağlantısı, başlık, açıklama, iki eylem ve not
export function BakeryIntro() {
  return <SectionHead eyebrow="Yeni: ekşi mayalı çavdar" eyebrowHref="#cavdar"
    title="Ekmeğin sabah 7'de kapında" lead="Gece yoğrulur, şafakta pişer. Siparişini akşam 10'a kadar ver, sabah sıcak sıcak gelsin."
    actions={[{ label: "Sipariş ver", href: "#siparis", iconEnd: arrowRight }, { label: "Fırını bul", href: "#harita", icon: mapPin }]}
    note="Cihangir, Firuzağa ve Çukurcuma'ya ücretsiz teslimat" />
}

import { SectionHead } from "march/landing"
import { Segmented, Toggle, Badge, Card } from "march/ui"
import { arrowRight, play } from "march/icons"

// SectionHead'in bütün özellikleri bir arada: üst etiket (kendi düğümün) ve bağlantısı, başlık, başlık öğesi ve kimliği,
// açıklama, eylemler (nesne ve kendi düğümün; ikon, varyant, tıklama, bağlantı), not, hiza, ölçek, genişlik, giriş
// hareketi, sınıf ve içerik (children)
export function SectionHeadLab() {
  let $size: "sm" | "md" | "lg" | "xl" = "md"
  let $align: "start" | "center" | "end" = "center"
  let $full = false
  let $h1 = false
  let $likes = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Ölçek" options={["sm", "md", "lg", "xl"]} bind:value={$size} />
        <Segmented aria-label="Hiza" options={[{ value: "start", label: "baş" }, { value: "center", label: "orta" }, { value: "end", label: "son" }]} bind:value={$align} />
        <Toggle label="Tam genişlik" bind:value={$full} />
        <Toggle label="Sayfa başlığı (h1)" bind:value={$h1} />
      </div>
    </Card>
    {() => {
      // Reveal yazdığı sınıfları bir kez okur: değerler burada okunur, değişince baş yeniden çizilir
      const h1 = $h1, size = $size, align = $align, full = $full
      return <SectionHead class="lab-head" eyebrow={<Badge tone="primary">Yeni</Badge>} eyebrowHref="#yenilikler"
        title={() => `Ekibinle birlikte üret (${$likes})`} as={h1 ? "h1" : "h3"} titleId="lab-head-title"
        lead="Planla, yaz, yayınla: hepsi aynı yerde."
        actions={[
          { label: "Beğen", icon: play, onClick: () => $likes++ },
          { label: "Belgeler", href: "#belgeler", iconEnd: arrowRight, variant: "ghost" },
          <a href="#iletisim" class="lab-own-action">Bize yaz</a> as Node,
        ]}
        note="14 gün ücretsiz · kart gerekmez"
        align={align} size={size} width={full ? "full" : "text"}
        reveal={{ effect: "up", stagger: 60 }}>
        <small class="lab-extra">2.400 ekip kullanıyor</small>
      </SectionHead>
    }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { SectionHeadLab } from "./SectionHeadLab.tsx"

// SectionHeadLab'in testleri: kaydedince Testler sekmesinde çalışır
test("üst etiket bir bağlantı; başlık kendi öğesi ve kimliğiyle", () => {
  const s = renderTest(() => <SectionHeadLab />)
  expect(s.get('.lab-head a.m-section-head-eyebrow')?.getAttribute("href")).toBe("#yenilikler")
  const h = s.get(".lab-head h3")!
  expect(h.id).toBe("lab-head-title")
  expect(h.textContent).toBe("Ekibinle birlikte üret (0)")
})

test("ilk eylem sayar; kendi düğümü ve not görünür", async () => {
  const s = renderTest(() => <SectionHeadLab />)
  await s.click("Beğen")
  expect(s.find("Ekibinle birlikte üret (1)")).not.toBe(null)
  expect(s.get(".lab-head .lab-own-action")?.getAttribute("href")).toBe("#iletisim")
  expect(s.text()).toContain("14 gün ücretsiz · kart gerekmez")
  expect(s.find("2.400 ekip kullanıyor")).not.toBe(null)
})

test("ölçek ve hiza sınıfları izler", async () => {
  const s = renderTest(() => <SectionHeadLab />)
  await s.click("xl")
  expect(s.get(".lab-head")?.classList.contains("m-section-head-xl")).toBe(true)
  await s.click("son")
  expect(s.get(".lab-head")?.classList.contains("m-section-head-end")).toBe(true)
})

test("tam genişlik ve h1", async () => {
  const s = renderTest(() => <SectionHeadLab />)
  await s.click("Tam genişlik")
  expect(s.get(".lab-head")?.classList.contains("m-section-head-full")).toBe(true)
  await s.click("Sayfa başlığı (h1)")
  expect(s.get(".lab-head h1")).not.toBe(null)
})
